        m, n = len(A), len(A[0])
        for i in range(m):
            max_row = i
            for j in range(i+1, m):
                if abs(A[j][i]) > abs(A[max_row][i]):
                    max_row = j
            A[i], A[max_row] = A[max_row], A[i]
            factor = 1 / A[i][i]
            for j in range(n):
                A[i][j] *= factor
            for j in range(m):
                if i != j:
                    factor = A[j][i]
                    for k in range(n):
                        A[j][k] -= factor * A[i][k]
        return A

    def matrix_multiply(A, B):
        m, n, p = len(A), len(B), len(B[0])
        C = [[0] * p for _ in range(m)]
        for i in range(m):
            for j in range(p):
                for k in range(n):
                    C[i][j] += A[i][k] * B[k][j]
        return C

    def incidence_complex(n, edges):
        V = list(range(n))
        E = [tuple(sorted(e)) for e in edges]
        F = []
        for i in range(1 << n):
            face = set()
            for j in range(n):
                if (i >> j) & 1:
                    face.add(j)
            if all(len(face.intersection(edge)) % 2 == len(edge) % 2 for edge in E):
                F.append(tuple(sorted(face)))
        return V, E, F

